import React,{useState} from 'react';
import {BookCover,ImageUpload,NovelForm} from '../../shared/presentation.tsx';
import {Icon} from '../../shared/icons.tsx';
import {usePreference,useResource} from '../../shared/state.js';
import {ResourceState} from '../../shared/ui.jsx';
import {useModules} from '../../modules/context.tsx';
import {Modal} from '../../shared/preferences.tsx';
import {GoalTargetEditor} from '../structure/GoalTargetEditor.jsx';
import {WritingOverview} from '../structure/Overview.jsx';
export function WorkDetail({call,novelId,tick,run,busy,onChapter,onPlanning,onMemory,onForeshadow}:any){
 const modules=useModules(),[editing,setEditing]=useState(false),[goalOpen,setGoalOpen]=useState(false),[lastChapter]=usePreference(`${novelId}:chapter`,'');
 const resource=useResource(()=>Promise.all([call('novel.get',{novelId}),call('writing.board.get',{novelId})]),[call,novelId,tick]);
 const update=(value:any)=>run(async()=>{const current=resource.value[0];await call('novel.update',{novelId,expectedRevision:current.revision,...value});setEditing(false);});
 return <div className="work-detail"><ResourceState resource={resource}>{resource.value&&(()=>{
  const [book,board]=resource.value,s=board.stats,goal=s.goal.target,percent=goal?Math.min(100,Math.round(s.words/goal*100)):0,remaining=Math.max(0,(goal||0)-s.words),chapter=board.chapters.find(c=>c.id===lastChapter)||[...board.chapters].reverse().find(c=>c.words>0)||board.chapters[0],plan=board.planning.find(p=>p.status!=='written')||board.planning[0],people=board.nodes.filter(n=>n.type==='character_card'),world=board.nodes.filter(n=>n.type!=='character_card'),recovered=board.foreshadows.filter(f=>f.status==='recovered'&&!f.review).length,pending=board.foreshadows.filter(f=>f.review||!['recovered','abandoned','open'].includes(f.status));
  return <><section className="book-detail-heading"><ImageUpload label={`替换 ${book.title} 的封面`} disabled={busy} onChange={coverImage=>update({coverImage})}><BookCover book={book}/></ImageUpload><div><span className="work-status">{book.workStatus||'创作中'}</span><h1>{book.title}</h1><p className="muted">{book.genre||'小说'} · 作品详情</p><button className="quiet-button" disabled={busy} onClick={()=>setEditing(true)}><Icon name="edit"/>编辑详情</button></div><span className="detail-ghost" aria-hidden="true">STORY</span></section>
   <p className="book-synopsis">{book.description||'给这个故事留一段简介。'}</p><button className="continue-writing" disabled={busy} onClick={()=>onChapter(chapter?.id)}><Icon name="edit"/><span><strong>{chapter?'继续写作':'开始写作'}</strong><small>{chapter?.title||'创建你的第一章'}</small></span><Icon name="arrow"/></button>
   <div className={`detail-metrics ${modules.foreshadow?'':'without-foreshadow'}`}><div><strong>{s.words.toLocaleString('zh-CN')}</strong><small>正文字数</small></div><div><strong>{s.chapters}</strong><small>章节</small></div>{modules.foreshadow&&<div><strong>{pending.length}</strong><small>待回收伏笔</small></div>}</div>
   <div className={`detail-panels ${modules.foreshadow?'':'without-foreshadow'}`}>{modules.overview&&<section className="detail-panel detail-goal"><div className="detail-goal-ring" style={{'--goal':percent+'%'} as React.CSSProperties} role="img" aria-label={goal?`写作目标 ${percent}%`:'尚未设置写作目标'}><span>{goal?percent+'%':'—'}</span></div><div className="grow"><h3>写作目标</h3><p>{goal?remaining?<>还需 <strong>{remaining.toLocaleString('zh-CN')}</strong> 字</>:'已达成目标':'设置你的正文目标'}</p><small>{goal?`目标 ${goal>=10000?goal/10000+' 万':goal.toLocaleString()}字`:'按自己的节奏开始'}</small></div><button className="icon-button" aria-label="调整写作目标" onClick={()=>setGoalOpen(true)}><Icon name="settings"/></button></section>}
    <button className="detail-panel detail-planning" onClick={()=>onPlanning(plan?.id)}><header><Icon name="route"/><h3>故事规划</h3></header><strong>{plan?.title||'等待你的灵感'}</strong><p>{plan?.summary||'在时间线与画布中安排故事'}</p><footer><span className="status-badge">{({idea:'讨论中',selected:'准备采用',written:'已写入正文',dropped:'暂不采用'} as any)[plan?.status]||'未开始'}</span><Icon name="arrow"/></footer></button>
    {modules.foreshadow&&<button className="detail-panel detail-shadows" onClick={()=>onForeshadow()}><header><Icon name="bookmark"/><h3>伏笔进度</h3></header><div className="shadow-score"><strong>{recovered}</strong><small>/ {board.foreshadows.length} 已完成</small></div><div className="detail-progress"><span style={{width:(board.foreshadows.length?recovered/board.foreshadows.length*100:0)+'%'}}/></div><footer><small>{pending.length?`${pending.length} 条待回收`:board.foreshadows.length?'已处理全部线索':'等待故事展开'}</small><Icon name="arrow"/></footer></button>}
    <button className="detail-panel detail-materials" onClick={()=>onMemory()}><span className="detail-avatars">{people.length?people.slice(0,2).map(p=><span key={p.id}>{p.avatarImage?<img src={p.avatarImage} alt=""/>:p.name.slice(0,1)}</span>):<span><Icon name="person"/></span>}</span><span className="grow"><h3>人物与世界</h3><small>{people.length} 位人物 · {world.length} 条世界设定</small></span><Icon name="arrow"/></button></div>
   {modules.overview&&<details className="detail-statistics"><summary>字数图表与详细统计</summary><WritingOverview {...{call,novelId,tick,run,busy,onChapter,onForeshadow}}/></details>}
   {editing&&<NovelForm initial={book} {...{busy}} close={()=>setEditing(false)} save={update}/>}{goalOpen&&<Modal title="写作目标" close={()=>setGoalOpen(false)}><GoalTargetEditor goal={s.goal} {...{call,novelId,run,busy}}/></Modal>}</>;
 })()}</ResourceState></div>;
}
